import {mathHTML} from './math-display.js?v=20261113-prose2';
import {validateStructureHandoff} from './structure-provenance.js?v=20261114-evidence1';
export {createStructureHandoff,validateStructureHandoff,structureHandoffForCalculation} from './structure-provenance.js?v=20261114-evidence1';
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Number(x.toPrecision(10)).toString();
const p=x=>'<p>'+esc(x)+'</p>';
const formula=x=>'<div class="sth-formula" tabindex="0">'+mathHTML(x,true)+'</div>';
const table=(caption,rows)=>'<div class="sth-scroll" tabindex="0"><table><caption>'+esc(caption)+'</caption><tbody>'+rows.map(([name,value])=>'<tr><th scope="row">'+esc(name)+'</th><td>'+esc(value)+'</td></tr>').join('')+'</tbody></table></div>';
const matrixNumber=x=>{const text=Number(x.toPrecision(12)).toString(),parts=text.split('e');return parts.length===2?parts[0]+'\\times10^{'+Number(parts[1])+'}':text;};
const matrix=m=>'\\begin{pmatrix}'+m.map(row=>row.map(matrixNumber).join('&')).join('\\\\')+'\\end{pmatrix}';

export function structureHandoffStatus(value,{analysis=null,groupNumber=null}={}){
 const v=validateStructureHandoff(value);if(!analysis)return{structure:'verified',numerical:'pending',bc:'pending',bilbao:'pending',associated:false,bcCount:0,bilbaoCount:0,irrepCount:0};
 const group=groupNumber??analysis.standardLabels?.group_number;
 const associated=group===v.structure.groupNumber&&analysis.magnetic===false&&analysis.doubleValued===v.doubleValued&&Array.isArray(analysis.k)&&analysis.k.length===3&&analysis.k.every((x,i)=>typeof x==='number'&&Number.isFinite(x)&&Math.abs(x-v.coordinates.bcK[i])<1e-8);
 if(!associated)return{structure:'verified',numerical:'mismatch',bc:'unassociated',bilbao:'unassociated',associated:false,bcCount:0,bilbaoCount:0,irrepCount:0};
 const mappings=Array.isArray(analysis.standardLabels?.mappings)?analysis.standardLabels.mappings:[],n=Array.isArray(analysis.irreps)?analysis.irreps.length:0;
 const bcCount=mappings.filter(m=>m.bc_label).length,bilbaoCount=mappings.filter(m=>m.bilbao_label).length;
 const verified=n>0&&analysis.validation?.passed===true&&analysis.validation?.orbitStabilizer===true&&typeof analysis.validation?.cocycleError==='number'&&Number.isFinite(analysis.validation.cocycleError)&&analysis.validation.cocycleError>=0&&analysis.validation.cocycleError<2e-5;
 return{structure:'verified',numerical:verified?'verified':'unverified',bc:!verified?'unverified':analysis.standardLabels?.bc_complete===true&&bcCount===n?'complete':'partial-or-unavailable',bilbao:!verified?'unverified':analysis.standardLabels?.bilbao_complete===true&&bilbaoCount===n?'complete':'partial-or-unavailable',associated:true,bcCount,bilbaoCount,irrepCount:n};
}

export function structureHandoffHTML(value,{analysis=null,groupNumber=null}={}){
 const v=validateStructureHandoff(value),s=structureHandoffStatus(v,{analysis,groupNumber}),kind={'teaching-example':"Idealized teaching structure",'user-file':"User-provided structure file",'user-text':"User-edited or pasted structure text"}[v.source.kind];
 const numerical=s.numerical==='pending'?"No representation calculation has been associated yet":s.numerical==='verified'?"The current numerical representation passed validation":s.numerical==='mismatch'?"The current group, wave vector, or representation type does not match the source":"The current representation result has not passed all numerical checks";
 const label=(status,count)=>status==='pending'?"Waiting for the current representation result":status==='unassociated'?"Unassociated; labels from other results are not used":status==='unverified'?"Numerical validation has not passed; labels are not confirmed":(status==='complete'?"Standard labels are complete for this result":"Partial or unavailable labels; validated numerical results are retained")+' · '+count+' / '+s.irrepCount;
 return"<section class=\"sth-panel\" data-structure-handoff aria-label=\"Source and conventions from structure to representation\"><h3>"+esc("Which structure is the source of this representation?")+'</h3><p class="sth-state">'+esc(v.source.filename||kind)+' · SG '+v.structure.groupNumber+' · '+esc(numerical)+'</p><details class="sth-details"><summary>'+esc("View file fingerprints and four validation statuses")+'</summary>'+table("Source and separate validation statuses",[[ "Source type",kind],["Original file name",v.source.filename||"No file name supplied"],[v.source.hashBasis==='file-bytes'?"SHA-256 of original file bytes":"SHA-256 of parsed UTF-8 text",v.source.sha256],["Source byte count",String(v.source.byteCount)],["SHA-256 of parsed text",v.source.textSHA256],["Parsed UTF-8 text byte count",String(v.source.textByteCount)],["Structure conversion","BC generators, atomic covariance, and coordinate transformation checked"],["Numerical representation",numerical],["BC label coverage",label(s.bc,s.bcCount)],["Bilbao label coverage",label(s.bilbao,s.bilbaoCount)]])+'</details>'+p("Conversion validation, numerical-representation validation, and the two standard naming schemes are four separate results. A validated numerical representation remains valid when standard names are unavailable.")+p(v.doubleValued?"A double-valued representation was explicitly selected. This choice does not infer SOC strength or magnetic order from the structure file.":"A single-valued representation was explicitly selected. The structure file alone does not determine whether a half-integer-spin representation is required, or identify SOC strength or magnetic order.")+'<details class="sth-details"><summary>'+esc("Expand tolerances, origin, and full-precision coordinates")+'</summary>'+table("Conversion request and crystal setting",[["space group",String(v.structure.groupNumber)+' · '+v.structure.international],["Hall number",String(v.structure.hallNumber)],["BZ type",v.structure.bzType||v.structure.bravais],["Input / BC atom count",v.structure.inputAtomCount+' / '+v.structure.bcAtomCount],["Symmetry tolerance / Å",String(v.settings.symprec)],["Angle tolerance/degree",String(v.settings.angleTolerance)],["Input k (fractional reciprocal coordinates of the original cell)",v.coordinates.inputK.map(String).join(', ')],["BC k (not folded modulo reciprocal lattice vectors)",v.coordinates.bcK.map(String).join(', ')],["Maximum atomic-covariance error / Å",String(v.verification.covarianceErrorAngstrom)],["Maximum atomic displacement on idealization / Å",String(v.verification.idealizationDisplacementAngstrom)],["spglib version",v.verification.spglibVersion]])+formula('x_{\\mathrm{BC}}=M x_{\\mathrm{input}}+q,\\qquad k_{\\mathrm{BC}}=M^{-T}k_{\\mathrm{input}}')+formula('M='+matrix(v.coordinates.M)+',\\quad q='+matrix(v.coordinates.q.map(x=>[x])))+p("Displayed formulas may abbreviate decimals; the JSON below retains the original numerical precision. Primitive-cell, origin, and Seitz-translation conventions affect the gauge of representation matrices; label suffixes or dimensions alone do not establish a correspondence.")+p(v.verification.scope)+v.verification.warnings.map(p).join('')+'<pre class="sth-json">'+esc(JSON.stringify({coordinates:v.coordinates,association:v.association},null,2))+'</pre></details>'+p("The summary retains file fingerprints and conversion settings, without original structure text or full input. It associates calculations; it neither establishes an experimental origin for a file nor replaces rerunning the checks.")+'<button type="button" class="secondary" data-structure-handoff-download>'+esc("Download this structure-source summary as JSON")+'</button></section>';
}

export function bindStructureHandoff({root,value,analysis=null,groupNumber=null,isCurrent=()=>true,download}={}){
 const snapshot=validateStructureHandoff(value),panel=root?.querySelector?.('[data-structure-handoff]'),button=panel?.querySelector('[data-structure-handoff-download]');let alive=true;
 const current=()=>alive&&panel&&root?.isConnected!==false&&root.querySelector('[data-structure-handoff]')===panel&&isCurrent();
 if(button){button.disabled=typeof download!=='function';button.onclick=()=>{if(!current()||panel.querySelector('[data-structure-handoff-download]')!==button||button.disabled)return;const status=structureHandoffStatus(snapshot,{analysis,groupNumber});download(JSON.stringify({structureHandoff:clone(snapshot),status},null,2),'structure-representation-source.json','application/json');};}
 const cleanup=()=>{alive=false;if(button)button.onclick=null;};cleanup.snapshot=()=>clone(snapshot);return cleanup;
}
